def cantor_pairing(x, y):
    # C(x, y) = T_{x+y} + y, where T_k = k(k+1)/2
    k = x + y
    t_k = k * (k + 1) // 2
    return t_k + y

N_max_100x100 = 0
for x in range(100):
    for y in range(100):
        f_xy = cantor_pairing(x, y)
        if f_xy % 2 != 0:
            N_max_100x100 += 1

print(f"N for Cantor Pairing Function (100x100): {N_max_100x100}")

